    "category": "Behavioral Interview Questions",
    "topic": "Teamwork & Coworker Dynamics",
    "question": "Have you ever worked in a team, and have you ever faced or handled a conflict within that team?",
    "answerHtml": "<div class=\"def\"><strong>Approach:</strong> Use a real or academic example. Structure: Situation → Conflict → Action → Result.</div>\nYes, while working on group assignments during CA studies, I often collaborated in teams. In one instance, a team member consistently missed deadlines, affecting everyone's work. I addressed it privately first — understood their workload issue — then we redistributed tasks fairly. The project was completed on time. Key: always address conflict directly, professionally, and without escalating prematurely. In a firm setting, I would follow the same approach while also keeping the supervisor informed if needed.\n<div class=\"tip\"><strong>Tip:</strong> Firms want to see maturity, not conflict avoidance. Show you can handle it without drama.</div>",
