    "answerHtml": "<ul><li>For today: assess urgency. If genuinely critical, stay and complete it</li><li>For the pattern: have a proactive conversation about workload planning: <em>\"I'm happy to stay late when needed, but can we plan ahead so I can manage my commitments?\"</em></li><li>In articleship: some late sitting is expected, especially during busy season</li></ul>",
