    "question": "How many years can a business loss or capital loss be carried forward?",
    "answerHtml": "<ul><li><strong>Business loss:</strong> 6 years (Section 56)</li><li><strong>Capital loss:</strong> 6 years (only against capital gains)</li><li><strong>Speculation business loss:</strong> can only offset speculation business profits; carry forward 6 years</li></ul>",
    "plainAnswer": "Business loss: 6 years (Section 56) Capital loss: 6 years (only against capital gains) Speculation business loss: can only offset speculation business profits; carry forward 6 years",
