    "category": "Taxation Principles",
    "topic": "Core Tax Concepts",
    "question": "Tax treatment for medical allowance, conveyance, and rent-free accommodation?",
    "answerHtml": "<ul><li><strong>Medical:</strong> Up to 10% of basic salary — exempt if hospitalization policy/bills certified by employer</li><li><strong>Conveyance:</strong> Provided as vehicle — 5% of vehicle cost included in salary; allowance for official use only — exempt; personal use — taxable</li><li><strong>Rent-free accommodation:</strong> Market rent or 45% of basic salary (whichever is higher) added to taxable salary</li></ul>",
    "plainAnswer": "Medical: Up to 10% of basic salary — exempt if hospitalization policy/bills certified by employer Conveyance: Provided as vehicle — 5% of vehicle cost included in salary; allowance for official use only — exempt; personal use — taxable Rent-free accommodation: Market rent or 45% of basic salary (whichever is higher) added to taxable salary",
