    "question": "Threshold for 'salaried person' classification, and which head is excluded?",
    "answerHtml": "A person is classified as a <strong>salaried person</strong> if 75% or more of their taxable income is from salary. The salaried person tax slabs (lower rates) apply. <strong>Capital gains (Section 37/37A)</strong> are excluded from this calculation.",
