    "question": "What is Sales Tax, and current federal/provincial GST rate?",
    "answerHtml": "<div class=\"def\">Sales Tax is an indirect tax on supply of goods and services.</div>\n<ul><li><strong>Federal GST (Sales Tax Act 1990):</strong> 18% standard rate (Finance Act 2023–24)</li><li><strong>Provincial GST on services:</strong> varies — Punjab: 16%, Sindh: 13%, KPK: 15%, Balochistan: 15%</li></ul>\n<div class=\"warn\">Rates change each Finance Act — verify from FBR/KPRA/SRB for current year.</div>",
    "plainAnswer": "Sales Tax is an indirect tax on supply of goods and services. Federal GST (Sales Tax Act 1990): 18% standard rate (Finance Act 2023–24) Provincial GST on services: varies — Punjab: 16%, Sindh: 13%, KPK: 15%, Balochistan: 15% Rates change each Finance Act — verify from FBR/KPRA/SRB for current year.",
