    "category": "Taxation Principles",
    "topic": "Core Tax Concepts",
    "question": "What are the canons of taxation?",
    "answerHtml": "Proposed by <strong>Adam Smith</strong>:<ul><li><strong>Canon of Equality:</strong> tax proportional to income/ability to pay</li><li><strong>Canon of Certainty:</strong> tax should be certain, not arbitrary</li><li><strong>Canon of Convenience:</strong> tax collected in convenient manner</li><li><strong>Canon of Economy:</strong> cost of collection should be minimal</li></ul>\nModern additions: Simplicity, Flexibility, Neutrality, Productivity.",
    "plainAnswer": "Proposed by Adam Smith : Canon of Equality: tax proportional to income/ability to pay Canon of Certainty: tax should be certain, not arbitrary Canon of Convenience: tax collected in convenient manner Canon of Economy: cost of collection should be minimal Modern additions: Simplicity, Flexibility, Neutrality, Productivity.",
    "idealAnswerPoints": [
      "Canon of Equality: tax proportional to income/ability to pay",
      "Canon of Certainty: tax should be certain, not arbitrary",
      "Canon of Convenience: tax collected in convenient manner",
      "Canon of Economy: cost of collection should be minimal"
    ],
