    "category": "Taxation Principles",
    "topic": "Core Tax Concepts",
    "question": "How do you convert accounting profit into taxable profit?",
    "answerHtml": "<span class=\"formula\">Taxable Profit = Accounting Profit\n+ Inadmissible expenses (added back)\n– Admissible deductions not in accounts (e.g., initial allowance)\n– Exempt income\n± Timing differences (accounting depreciation vs. tax depreciation)\n= Taxable Income</span>",
    "plainAnswer": "Taxable Profit = Accounting Profit + Inadmissible expenses (added back) – Admissible deductions not in accounts (e.g., initial allowance) – Exempt income ± Timing differences (accounting depreciation vs. tax depreciation) = Taxable Income",
