    "category": "Taxation Principles",
    "topic": "Core Tax Concepts",
    "question": "What is VAT (Value Added Tax)?",
    "answerHtml": "<div class=\"def\">VAT is a multi-stage consumption tax levied on the value added at each stage of production/distribution. Pakistan's Sales Tax is VAT-based in mechanism (input-output credit system).</div>\nKey: each stage pays tax only on the value it adds, not the full price. This avoids cascading taxation.",
    "plainAnswer": "VAT is a multi-stage consumption tax levied on the value added at each stage of production/distribution. Pakistan's Sales Tax is VAT-based in mechanism (input-output credit system). Key: each stage pays tax only on the value it adds, not the full price. This avoids cascading taxation.",
