    "plainAnswer": "Progressive Regressive Rate increases with income Rate decreases as income rises Burdens high-income more Burdens low-income more (proportionally) Pakistan income tax — salaried Sales tax (same rate for all) In Pakistan: Income tax = progressive; Sales tax = regressive (affects poor more proportionally).",
