    "question": "What are individual income tax slabs for salaried persons (FY 2024–25)?",
    "answerHtml": "<div class=\"warn\">Verify from FBR — indicative slabs below:</div>\n<table><tr><th>Annual Income (Rs.)</th><th>Rate</th></tr>\n<tr><td>Up to 600,000</td><td>0%</td></tr>\n<tr><td>600,001 – 1,200,000</td><td>5% of excess over 600,000</td></tr>\n<tr><td>1,200,001 – 2,200,000</td><td>Rs.30,000 + 15% excess over 1,200,000</td></tr>\n<tr><td>2,200,001 – 3,200,000</td><td>Rs.180,000 + 25% excess over 2,200,000</td></tr>\n<tr><td>3,200,001 – 4,100,000</td><td>Rs.430,000 + 30% excess over 3,200,000</td></tr>\n<tr><td>Above 4,100,000</td><td>Rs.700,000 + 35% excess over 4,100,000</td></tr></table>",
