    "module": "taxation",
    "category": "Taxation Principles",
    "topic": "Core Tax Concepts",
    "question": "What is the Presumptive Tax Regime (PTR)?",
    "answerHtml": "<div class=\"def\">PTR: Tax charged on gross receipts at a fixed rate without deduction of expenses. WHT deducted at source is the final tax liability.</div>\nApplied to: importers, exporters, contractors, suppliers to government. Example: contractor receives Rs.10M — 7% WHT deducted = Rs.700,000 as final tax. No further return required for that income.",
    "plainAnswer": "PTR: Tax charged on gross receipts at a fixed rate without deduction of expenses. WHT deducted at source is the final tax liability. Applied to: importers, exporters, contractors, suppliers to government. Example: contractor receives Rs.10M — 7% WHT deducted = Rs.700,000 as final tax. No further return required for that income.",
