    "question": "What is Federal Excise Duty (FED)?",
    "answerHtml": "<div class=\"def\">FED: Indirect tax on specific manufactured/imported goods and services under Federal Excise Act 2005.</div>\nApplied on: tobacco, cement, beverages, natural gas, banking services, insurance, air travel. Can be specific (per unit) or ad valorem (% of value). Administered by FBR.",
