    "topic": "Core Tax Concepts",
    "question": "What is Customs Duty and how is it calculated?",
    "answerHtml": "<div class=\"def\">Tax on goods imported/exported under Customs Act 1969.</div>\nCalculated on: customs value (transaction value per WTO agreement) × tariff rate from Pakistan Customs Tariff.<br>\nAdditional levies at import stage: GST, FED, and WHT on imports (advance tax).",
    "plainAnswer": "Tax on goods imported/exported under Customs Act 1969. Calculated on: customs value (transaction value per WTO agreement) × tariff rate from Pakistan Customs Tariff. Additional levies at import stage: GST, FED, and WHT on imports (advance tax).",
