    "question": "What is Section 111 — unexplained income?",
    "answerHtml": "<div class=\"def\">Section 111: If a person cannot explain the source of income, asset or expenditure — FBR adds it to taxable income and taxes it.</div>\nPrevents money laundering. Burden of proof on taxpayer. FBR can issue notice if lifestyle is inconsistent with declared income.",
