    "module": "taxation",
    "category": "Taxation Principles",
    "topic": "Core Tax Concepts",
    "question": "What is General Anti-Avoidance Rule (GAAR)?",
    "answerHtml": "<div class=\"def\">GAAR (Section 109): FBR can recharacterize transactions that have no commercial substance and exist only to reduce tax.</div>\nTargets aggressive tax planning. Even legal tax avoidance can be challenged under GAAR if the scheme lacks genuine commercial purpose. Tax evasion = illegal; Tax avoidance = legal but challengeable under GAAR.",
    "plainAnswer": "GAAR (Section 109): FBR can recharacterize transactions that have no commercial substance and exist only to reduce tax. Targets aggressive tax planning. Even legal tax avoidance can be challenged under GAAR if the scheme lacks genuine commercial purpose. Tax evasion = illegal; Tax avoidance = legal but challengeable under GAAR.",
