    "question": "Tax implications of a partnership / AOP?",
    "answerHtml": "<ul>\n<li>AOP taxed as a separate entity at progressive individual rates</li>\n<li>Partner's share of AOP profit: <strong>exempt</strong> in partner's hands (no double tax)</li>\n<li>AOP must file its own return</li>\n<li>AOP losses carried forward by AOP itself (6 years), not by individual partners</li></ul>",
