    "topic": "Core Tax Concepts",
    "question": "What is transfer pricing?",
    "answerHtml": "<div class=\"def\">Transfer pricing: prices charged in transactions between associated/related parties must be at arm's length — same as unrelated parties would charge.</div>\nPakistan follows OECD guidelines (Section 108 ITO). FBR adjusts income if prices are not arm's length. Critical for multinationals moving profits between jurisdictions.",
    "plainAnswer": "Transfer pricing: prices charged in transactions between associated/related parties must be at arm's length — same as unrelated parties would charge. Pakistan follows OECD guidelines (Section 108 ITO). FBR adjusts income if prices are not arm's length. Critical for multinationals moving profits between jurisdictions.",
