    "plainAnswer": "Normal tax year: 1 July to 30 June (year is named after the year it ends — Tax Year 2025 = July 2024 to June 2025). Special year-end (e.g., Dec 31): requires Commissioner's approval and is labeled by year of ending. Return due dates: Individuals/AOPs = 30 Sept; Companies (June year-end) = 31 Dec.",
