    "answerHtml": "<span class=\"formula\">Taxable Income = Accounting Profit\n+ Inadmissible expenses (added back)\n+ Accounting depreciation (added back)\n– Tax depreciation (initial allowance + tax dep.)\n– Exempt income\n– Allowable deductions not in accounts\n= Taxable Income</span>",
    "plainAnswer": "Taxable Income = Accounting Profit + Inadmissible expenses (added back) + Accounting depreciation (added back) – Tax depreciation (initial allowance + tax dep.) – Exempt income – Allowable deductions not in accounts = Taxable Income",
