    "answerHtml": "<ul>\n<li><strong>Excess input tax (input > output):</strong> Can be carried forward to next tax period</li>\n<li><strong>Refund:</strong> Exporters (zero-rated) can claim refund of excess input tax from FBR</li>\n<li>Refund claim must be filed within <strong>2 years</strong> of the end of the relevant tax period</li></ul>",
