    "question": "What is a statutory meeting and its timing post-incorporation?",
    "answerHtml": "<div class=\"def\">Statutory meeting: held once, between 3 months and 6 months after commencement of business. Only for public companies.</div>\nAgenda: discuss the Statutory Report covering allotment of shares, receipts, directors, preliminary contracts.",
