    "question": "What is an EOGM and who has authority to call it?",
    "answerHtml": "<div class=\"def\">Extraordinary General Meeting (EOGM): meeting called outside of the AGM schedule for urgent business.</div>\n<strong>Called by:</strong><ul><li>Board of Directors on their own</li><li>Directors on requisition by members holding ≥10% of paid-up voting capital</li><li>Members themselves if directors don't call within 21 days of requisition</li><li>Court order</li></ul>",
