    "question": "What are the ineligibilities/disqualifications for a director?",
    "answerHtml": "Under Companies Act 2017, a person CANNOT be a director if:<ul><li>Minor (under 18)</li><li>Of unsound mind (adjudged by court)</li><li>Insolvent/bankrupt</li><li>Convicted of fraud, breach of trust, or money laundering</li><li>Not an NTN holder (tax non-filer disqualification)</li><li>Removed from directorship of any company in last 5 years by SECP/court</li></ul>",
