    "id": "faq_205",
    "module": "companylaw",
    "category": "Business & Company Law",
    "topic": "Meetings, Directors & Corporate Structure",
    "question": "Who fills a casual vacancy for a director?",
    "answerHtml": "<ul><li>A <strong>casual vacancy</strong> (director dies, resigns mid-term) is filled by the <strong>Board of Directors</strong> at the next board meeting</li><li>The new director serves only for the remainder of the original term</li><li>If BOD fails to fill it within 90 days: <strong>SECP can appoint</strong> the director</li></ul>",
