    "answerHtml": "<ul><li><strong>Yes</strong> — a member can appoint a proxy to attend and vote on their behalf</li><li>A proxy need <strong>not</strong> be a member of the company</li><li>Proxy form must be submitted 48 hours before the meeting</li><li><strong>Voting methods:</strong> Show of hands (default) or poll (on demand)</li><li>Poll can be demanded by: Chairman, 5 members, members with ≥10% voting rights</li></ul>",
