    "topic": "Meetings, Directors & Corporate Structure",
    "question": "What is limited liability?",
    "answerHtml": "<div class=\"def\">Liability of shareholders is limited to the amount unpaid on their shares.</div>\nApplies to <strong>shareholders</strong> — not to the company itself (which is liable for all its debts). Directors are personally liable only if they breach fiduciary duties or sign personal guarantees.",
