    "module": "companylaw",
    "category": "Business & Company Law",
    "topic": "Meetings, Directors & Corporate Structure",
    "question": "What is the doctrine of ultra vires in company law?",
    "answerHtml": "<div class=\"def\">Ultra vires: An act done by a company that is beyond the powers granted to it by its Memorandum of Association.</div>\nSuch acts are void and cannot be ratified by shareholders. Protects creditors and shareholders from management exceeding company's stated objects. Companies Act 2017 has relaxed this — companies can now have broad objects clauses.",
    "plainAnswer": "Ultra vires: An act done by a company that is beyond the powers granted to it by its Memorandum of Association. Such acts are void and cannot be ratified by shareholders. Protects creditors and shareholders from management exceeding company's stated objects. Companies Act 2017 has relaxed this — companies can now have broad objects clauses.",
    "idealAnswerPoints": [
      "Standard professional application",
      "Clear reasoning with standard references"
    ],
    "difficulty": "Intermediate",
    "suitableRoles": [
      "Audit Trainee (Articleship)",
      "CA Articleship",
      "ACCA Trainee"
    ],
