    "topic": "Meetings, Directors & Corporate Structure",
    "question": "Difference between preference shares and ordinary shares?",
    "answerHtml": "<table><tr><th>Preference Shares</th><th>Ordinary Shares</th></tr>\n<tr><td>Fixed dividend (priority)</td><td>Variable dividend (residual)</td></tr>\n<tr><td>Priority in winding up</td><td>Last in winding up</td></tr>\n<tr><td>Usually no voting rights</td><td>Voting rights</td></tr>\n<tr><td>Can be cumulative (unpaid dividend accumulates)</td><td>Non-cumulative</td></tr></table>",
    "plainAnswer": "Preference Shares Ordinary Shares Fixed dividend (priority) Variable dividend (residual) Priority in winding up Last in winding up Usually no voting rights Voting rights Can be cumulative (unpaid dividend accumulates) Non-cumulative",
