    "category": "Business & Company Law",
    "topic": "Meetings, Directors & Corporate Structure",
    "question": "What is the difference between merger and acquisition?",
    "answerHtml": "<table><tr><th>Merger</th><th>Acquisition</th></tr>\n<tr><td>Two companies combine to form one new entity</td><td>One company takes over another</td></tr>\n<tr><td>Both entities dissolve; new one formed</td><td>Target may continue as subsidiary</td></tr>\n<tr><td>Equal footing (theoretically)</td><td>Acquirer dominates</td></tr></table>\nRegulated by SECP and Competition Commission of Pakistan (CCP).",
