    "module": "audit",
    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "Difference between internal audit and external audit?",
    "answerHtml": "<table><tr><th>Feature</th><th>Internal Audit</th><th>External Audit</th></tr>\n<tr><td>Appointed by</td><td>Management/BOD</td><td>Shareholders</td></tr>\n<tr><td>Objective</td><td>Add value, improve operations</td><td>Express opinion on financial statements</td></tr>\n<tr><td>Independence</td><td>Functionally independent</td><td>Fully independent</td></tr>\n<tr><td>Report to</td><td>Audit Committee/Management</td><td>Shareholders (in audit report)</td></tr>\n<tr><td>Mandatory</td><td>Depends on company</td><td>Legally required for most entities</td></tr></table>",
    "plainAnswer": "Feature Internal Audit External Audit Appointed by Management/BOD Shareholders Objective Add value, improve operations Express opinion on financial statements Independence Functionally independent Fully independent Report to Audit Committee/Management Shareholders (in audit report) Mandatory Depends on company Legally required for most entities",
