    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "Difference between reasonable assurance and limited assurance?",
    "answerHtml": "<table><tr><th>Reasonable Assurance</th><th>Limited Assurance</th></tr>\n<tr><td>High level — audit (ISA)</td><td>Moderate level — review engagement (ISRE 2400)</td></tr>\n<tr><td>Positive conclusion: \"…presents fairly\"</td><td>Negative conclusion: \"Nothing came to attention…\"</td></tr>\n<tr><td>Extensive procedures</td><td>Limited procedures (mainly inquiry, analytics)</td></tr></table>",
    "plainAnswer": "Reasonable Assurance Limited Assurance High level — audit (ISA) Moderate level — review engagement (ISRE 2400) Positive conclusion: \"…presents fairly\" Negative conclusion: \"Nothing came to attention…\" Extensive procedures Limited procedures (mainly inquiry, analytics)",
