    "id": "faq_239",
    "module": "audit",
    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "What are financial statement assertions?",
    "answerHtml": "<strong>Balance Sheet (CAVE):</strong><ul><li><strong>C</strong>ompleteness — all assets/liabilities recorded</li><li><strong>A</strong>ccuracy/Valuation — correctly valued</li><li><strong>V</strong>aluation and allocation</li><li><strong>E</strong>xistence — assets/liabilities actually exist</li><li>Rights & Obligations — company has rights to assets, owes liabilities</li><li>Classification & Presentation</li></ul>\n<strong>P&L (COCA):</strong> Completeness, Occurrence/Existence, Cut-off, Accuracy",
    "plainAnswer": "Balance Sheet (CAVE): C ompleteness — all assets/liabilities recorded A ccuracy/Valuation — correctly valued V aluation and allocation E xistence — assets/liabilities actually exist Rights & Obligations — company has rights to assets, owes liabilities Classification & Presentation P&L (COCA): Completeness, Occurrence/Existence, Cut-off, Accuracy",
    "idealAnswerPoints": [
      "C ompleteness — all assets/liabilities recorded",
      "A ccuracy/Valuation — correctly valued",
      "V aluation and allocation",
      "E xistence — assets/liabilities actually exist"
    ],
