    "question": "Difference between vouching and tracing?",
    "answerHtml": "<table><tr><th>Vouching</th><th>Tracing</th></tr>\n<tr><td>From records to source documents</td><td>From source documents to records</td></tr>\n<tr><td>Tests for <strong>occurrence/validity</strong></td><td>Tests for <strong>completeness</strong></td></tr>\n<tr><td>E.g., journal entry → invoice</td><td>E.g., invoice → journal entry</td></tr></table>",
    "plainAnswer": "Vouching Tracing From records to source documents From source documents to records Tests for occurrence/validity Tests for completeness E.g., journal entry → invoice E.g., invoice → journal entry",
