    "id": "faq_243",
    "module": "audit",
    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "What are analytical procedures?",
    "answerHtml": "<div class=\"def\">Analytical procedures: evaluation of financial information through analysis of plausible relationships among financial and non-financial data.</div>\nUsed at: planning (risk assessment) and completion stages.<br>\n<strong>Key ratios interpretations:</strong><ul><li>Receivable turnover increased → collecting faster (good) or aggressive revenue recognition (risk)</li><li>Acid test decreased → liquidity concerns</li><li>Interest coverage decreased → risk of going concern</li></ul>",
    "plainAnswer": "Analytical procedures: evaluation of financial information through analysis of plausible relationships among financial and non-financial data. Used at: planning (risk assessment) and completion stages. Key ratios interpretations: Receivable turnover increased → collecting faster (good) or aggressive revenue recognition (risk) Acid test decreased → liquidity concerns Interest coverage decreased → risk of going concern",
    "idealAnswerPoints": [
      "Receivable turnover increased → collecting faster (good) or aggressive revenue recognition (risk)",
      "Acid test decreased → liquidity concerns",
      "Interest coverage decreased → risk of going concern"
    ],
