    "answerHtml": "<table><tr><th>Opinion</th><th>When Issued</th></tr>\n<tr><td>Unmodified (Clean)</td><td>FS present fairly, no issues</td></tr>\n<tr><td>Qualified</td><td>Material but not pervasive misstatement OR scope limitation</td></tr>\n<tr><td>Adverse</td><td>Material AND pervasive misstatement</td></tr>\n<tr><td>Disclaimer</td><td>Material AND pervasive scope limitation (unable to obtain evidence)</td></tr></table>",
    "plainAnswer": "Opinion When Issued Unmodified (Clean) FS present fairly, no issues Qualified Material but not pervasive misstatement OR scope limitation Adverse Material AND pervasive misstatement Disclaimer Material AND pervasive scope limitation (unable to obtain evidence)",
