    "module": "audit",
    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "What is a Key Audit Matter (KAM)?",
    "answerHtml": "<div class=\"def\">KAM (ISA 701): matters that in the auditor's professional judgment were most significant in the audit of the current period financial statements.</div>\n<ul><li><strong>Required for:</strong> listed entities</li><li><strong>Not required for:</strong> non-listed private companies</li><li>Selected from: matters communicated to those charged with governance</li></ul>",
    "plainAnswer": "KAM (ISA 701): matters that in the auditor's professional judgment were most significant in the audit of the current period financial statements. Required for: listed entities Not required for: non-listed private companies Selected from: matters communicated to those charged with governance",
