    "id": "faq_248",
    "module": "audit",
    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "Going concern assumption — how evaluated, implications?",
    "answerHtml": "<ul><li>Auditor assesses management's assessment of going concern (ISA 570)</li><li>Indicators of concern: net liabilities, loan defaults, inability to pay debts, loss of key customers</li></ul>\n<strong>Implications:</strong><ul><li>Going concern appropriate → unmodified opinion (possibly EOM if significant uncertainty)</li><li>Not appropriate but management uses it → adverse opinion</li><li>Going concern appropriate but management won't disclose significant uncertainty → qualified/adverse</li></ul>",
    "plainAnswer": "Auditor assesses management's assessment of going concern (ISA 570) Indicators of concern: net liabilities, loan defaults, inability to pay debts, loss of key customers Implications: Going concern appropriate → unmodified opinion (possibly EOM if significant uncertainty) Not appropriate but management uses it → adverse opinion Going concern appropriate but management won't disclose significant uncertainty → qualified/adverse",
    "idealAnswerPoints": [
      "Auditor assesses management's assessment of going concern (ISA 570)",
      "Indicators of concern: net liabilities, loan defaults, inability to pay debts, loss of key customers",
      "Going concern appropriate → unmodified opinion (possibly EOM if significant uncertainty)",
      "Not appropriate but management uses it → adverse opinion"
    ],
