    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "How do you deal with situations involving fraud (ISA 240)?",
    "answerHtml": "<div class=\"def\">Auditor's responsibility: design procedures to detect material misstatements due to fraud.</div>\n<strong>Fraud risk factors:</strong> pressure (incentive), opportunity (weak controls), rationalization.<br>\n<strong>Auditor's response:</strong><ul><li>More unpredictable procedures</li><li>Report to management / those charged with governance</li><li>If management involved: report to regulatory/legal authorities</li><li>Cannot guarantee detection of all fraud</li></ul>",
    "plainAnswer": "Auditor's responsibility: design procedures to detect material misstatements due to fraud. Fraud risk factors: pressure (incentive), opportunity (weak controls), rationalization. Auditor's response: More unpredictable procedures Report to management / those charged with governance If management involved: report to regulatory/legal authorities Cannot guarantee detection of all fraud",
