    "topic": "Core Audit Concepts",
    "question": "Fundamental principles of ethics for an auditor?",
    "answerHtml": "From IESBA/ICAP Code of Ethics:<ul><li><strong>Integrity:</strong> straightforward and honest</li><li><strong>Objectivity:</strong> not compromised by bias or conflict of interest</li><li><strong>Professional Competence and Due Care</strong></li><li><strong>Confidentiality:</strong> not disclose client info without authority</li><li><strong>Professional Behaviour:</strong> comply with laws and avoid discrediting the profession</li></ul>\n<strong>Threats to independence:</strong> Self-interest, Self-review, Advocacy, Familiarity, Intimidation",
    "plainAnswer": "From IESBA/ICAP Code of Ethics: Integrity: straightforward and honest Objectivity: not compromised by bias or conflict of interest Professional Competence and Due Care Confidentiality: not disclose client info without authority Professional Behaviour: comply with laws and avoid discrediting the profession Threats to independence: Self-interest, Self-review, Advocacy, Familiarity, Intimidation",
