    "topic": "Core Audit Concepts",
    "question": "What is professional skepticism and why is it important?",
    "answerHtml": "<div class=\"def\">Professional skepticism: A questioning mind and critical assessment of evidence, without assuming management is dishonest or honest (ISA 200).</div>\nImportant for: identifying fraud risks, unusual transactions, and not over-relying on management representations. Critical during estimates, related party transactions, and revenue recognition.",
    "plainAnswer": "Professional skepticism: A questioning mind and critical assessment of evidence, without assuming management is dishonest or honest (ISA 200). Important for: identifying fraud risks, unusual transactions, and not over-relying on management representations. Critical during estimates, related party transactions, and revenue recognition.",
