    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "What is audit evidence — sufficient and appropriate (ISA 500)?",
    "answerHtml": "<div class=\"def\">All information used by the auditor to draw conclusions on which the audit opinion is based.</div>\n<strong>Sufficient:</strong> Quantity — more for high-risk areas<br>\n<strong>Appropriate:</strong> Quality — relevance and reliability<br>\n<strong>Reliability hierarchy:</strong> External confirmation > Auditor-generated > Client-generated external > Internal client documents",
    "plainAnswer": "All information used by the auditor to draw conclusions on which the audit opinion is based. Sufficient: Quantity — more for high-risk areas Appropriate: Quality — relevance and reliability Reliability hierarchy: External confirmation > Auditor-generated > Client-generated external > Internal client documents",
