    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "What is the audit committee and its role?",
    "answerHtml": "<div class=\"def\">Sub-committee of the Board overseeing financial reporting, internal controls, and audit.</div>\n<strong>Roles:</strong><ul>\n<li>Recommend appointment/removal of external auditor</li>\n<li>Review financial statements before BOD approval</li>\n<li>Oversee internal audit</li>\n<li>Review related party transactions</li></ul>\nRequired for all listed companies under SECP Code of Corporate Governance.",
    "plainAnswer": "Sub-committee of the Board overseeing financial reporting, internal controls, and audit. Roles: Recommend appointment/removal of external auditor Review financial statements before BOD approval Oversee internal audit Review related party transactions Required for all listed companies under SECP Code of Corporate Governance.",
