    "answerHtml": "<div class=\"def\">Written letter from management confirming representations made during the audit and acknowledging responsibility for the financial statements.</div>\nMust be obtained before audit report is signed. Contains: FS prepared per IFRS, all information provided, no undisclosed liabilities, subsequent events disclosed.\n<div class=\"warn\">It supplements other audit evidence — it is NOT a substitute for it.</div>",
