    "answerHtml": "<ul>\n<li><strong>Between year-end and audit report date:</strong> Auditor actively performs procedures — must respond to all events found</li>\n<li><strong>After report date but before FS issued:</strong> Discuss with management — may need to amend FS and re-issue report</li>\n<li><strong>After FS issued:</strong> No ongoing obligation, but if a fact becomes known — take appropriate action</li></ul>",
    "plainAnswer": "Between year-end and audit report date: Auditor actively performs procedures — must respond to all events found After report date but before FS issued: Discuss with management — may need to amend FS and re-issue report After FS issued: No ongoing obligation, but if a fact becomes known — take appropriate action",
