    "answerHtml": "<div class=\"def\">Internal control: Process providing reasonable assurance about achieving objectives in operations, reporting, and compliance.</div>\n<strong>COSO 5 components:</strong><ul>\n<li><strong>C</strong>ontrol Environment (tone at top)</li>\n<li><strong>R</strong>isk Assessment</li>\n<li><strong>C</strong>ontrol Activities (authorizations, segregation of duties)</li>\n<li><strong>I</strong>nformation & Communication</li>\n<li><strong>M</strong>onitoring</li></ul>",
