    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "What is segregation of duties?",
    "answerHtml": "<div class=\"def\">No single person controls all phases of a transaction — authorization, recording, custody, and reconciliation must be separate.</div>\nPrevents fraud and errors. Example: person who approves a payment should not also record it and reconcile the bank statement. Critical for cash, payroll, and procurement.",
    "plainAnswer": "No single person controls all phases of a transaction — authorization, recording, custody, and reconciliation must be separate. Prevents fraud and errors. Example: person who approves a payment should not also record it and reconcile the bank statement. Critical for cash, payroll, and procurement.",
