    "answerHtml": "<div class=\"def\">ISQM 1: International Standard on Quality Management — requires firms to design and implement a system of quality management over audit engagements.</div>\n<strong>Key elements:</strong><ul>\n<li>Leadership responsibilities for quality</li>\n<li>Independence and ethical requirements</li>\n<li>Engagement acceptance and continuance</li>\n<li>Human resources / competence</li>\n<li>Engagement performance standards</li>\n<li>Monitoring and remediation</li></ul>",
