    "answerHtml": "<div class=\"def\">An objective evaluation of significant judgments made by the engagement team before the audit report is issued — for listed entities and high-risk engagements.</div>\nPerformed by a separate, senior reviewer not involved in the engagement. Provides additional quality check on audit opinions on complex or material matters.",
