    "id": "faq_266",
    "module": "audit",
    "category": "Audit & Assurance",
    "topic": "Core Audit Concepts",
    "question": "What is the difference between detection risk and control risk?",
    "answerHtml": "<table><tr><th>Control Risk</th><th>Detection Risk</th></tr>\n<tr><td>Risk that internal controls fail to prevent/detect misstatement</td><td>Risk that auditor's procedures fail to detect misstatement</td></tr>\n<tr><td>Assessed — auditor cannot control it</td><td>Controlled — auditor adjusts procedures to manage it</td></tr>\n<tr><td>High CR → auditor increases substantive testing</td><td>Lower detection risk = more substantive work</td></tr></table>",
    "plainAnswer": "Control Risk Detection Risk Risk that internal controls fail to prevent/detect misstatement Risk that auditor's procedures fail to detect misstatement Assessed — auditor cannot control it Controlled — auditor adjusts procedures to manage it High CR → auditor increases substantive testing Lower detection risk = more substantive work",
    "idealAnswerPoints": [
      "Standard professional application",
      "Clear reasoning with standard references"
    ],
