    "answerHtml": "<ul>\n<li>Send positive confirmation letters to a sample of debtors</li>\n<li>Review subsequent cash receipts (payments after year-end)</li>\n<li>Assess adequacy of bad debt provision (review aging analysis)</li>\n<li>Agree balance to sales invoices and delivery notes</li>\n<li>Check cut-off — sales near year-end genuinely earned</li>\n<li>Analytical procedures — receivables days vs. prior year</li></ul>",
