    "question": "What is ISA 315 — understanding the entity and its environment?",
    "answerHtml": "<div class=\"def\">ISA 315: Requires the auditor to obtain understanding of the entity and its environment (including internal controls) to identify and assess risks of material misstatement.</div>\n<strong>Key areas to understand:</strong><ul>\n<li>Industry, regulatory, and external environment</li>\n<li>Nature of the entity (operations, ownership, governance)</li>\n<li>Entity's objectives, strategies, and business risks</li>\n<li>Financial performance measurement</li>\n<li>Internal controls relevant to financial reporting</li></ul>",
