    "module": "far",
    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "Difference between IRR and NPV?",
    "answerHtml": "<table><tr><th>NPV</th><th>IRR</th></tr>\n<tr><td>Net Present Value: PV of inflows minus initial investment</td><td>Internal Rate of Return: discount rate at which NPV = 0</td></tr>\n<tr><td>Absolute value (Rs.)</td><td>Percentage (%)</td></tr>\n<tr><td>Accept if NPV > 0</td><td>Accept if IRR > cost of capital</td></tr></table>\n<span class=\"formula\">NPV = Σ [CFt / (1+r)^t] – Initial Investment</span>",
    "plainAnswer": "NPV IRR Net Present Value: PV of inflows minus initial investment Internal Rate of Return: discount rate at which NPV = 0 Absolute value (Rs.) Percentage (%) Accept if NPV > 0 Accept if IRR > cost of capital NPV = Σ [CFt / (1+r)^t] – Initial Investment",
    "idealAnswerPoints": [
      "Standard professional application",
      "Clear reasoning with standard references"
    ],
