    "question": "Effect on retained earnings of increase in revenue and expenses?",
    "answerHtml": "<ul><li>Revenue increases → Net profit increases → Retained earnings increase</li><li>Expenses increase → Net profit decreases → Retained earnings decrease</li></ul>\n<span class=\"formula\">Retained Earnings (closing) = Retained Earnings (opening) + Net Profit – Dividends</span>",
