    "topic": "Core Concepts & Standards",
    "question": "How do you calculate depreciation? Straight-line vs. reducing balance?",
    "answerHtml": "<span class=\"formula\">SLM: (Cost – Residual Value) / Useful Life = Annual Depreciation\nRBM: Written Down Value × Rate% = Annual Depreciation</span>\n<table><tr><th>SLM</th><th>Reducing Balance (DBM)</th></tr>\n<tr><td>Equal charge each year</td><td>Higher charge early years</td></tr>\n<tr><td>Simple, stable P&L impact</td><td>Matches economic use of fast-depreciating assets</td></tr></table>",
    "plainAnswer": "SLM: (Cost – Residual Value) / Useful Life = Annual Depreciation RBM: Written Down Value × Rate% = Annual Depreciation SLM Reducing Balance (DBM) Equal charge each year Higher charge early years Simple, stable P&L impact Matches economic use of fast-depreciating assets",
