    "topic": "Core Concepts & Standards",
    "question": "FIFO vs AVCO (Weighted Average)?",
    "answerHtml": "<table><tr><th>FIFO</th><th>AVCO</th></tr>\n<tr><td>First In First Out: oldest stock issued first</td><td>Weighted average cost of all stock used</td></tr>\n<tr><td>Closing stock valued at recent prices</td><td>Smoother cost over time</td></tr>\n<tr><td>Higher profit in rising prices</td><td>Moderate profit</td></tr></table>\nIAS 2 allows both. LIFO is <strong>prohibited</strong> under IFRS.",
    "plainAnswer": "FIFO AVCO First In First Out: oldest stock issued first Weighted average cost of all stock used Closing stock valued at recent prices Smoother cost over time Higher profit in rising prices Moderate profit IAS 2 allows both. LIFO is prohibited under IFRS.",
