    "answerHtml": "<span class=\"formula\">Recoverable Amount = Higher of: (a) Fair Value Less Costs to Sell (FVLCTS), OR (b) Value in Use (VIU)</span>\n<strong>VIU:</strong> Present value of future cash flows expected from continuing use and ultimate disposal of the asset.\n<span class=\"formula\">VIU = Σ [Expected Cash Flows / (1+discount rate)^t]</span>",
    "plainAnswer": "Recoverable Amount = Higher of: (a) Fair Value Less Costs to Sell (FVLCTS), OR (b) Value in Use (VIU) VIU: Present value of future cash flows expected from continuing use and ultimate disposal of the asset. VIU = Σ [Expected Cash Flows / (1+discount rate)^t]",
