    "question": "What is a qualifying asset under IAS 23?",
    "answerHtml": "<div class=\"def\">A qualifying asset is one that necessarily takes a substantial period of time to get ready for its intended use or sale.</div>\n<strong>Examples:</strong> manufacturing plants, power generation facilities, investment property under construction, intangible assets in development.<br>\n<strong>Start capitalizing borrowing costs:</strong> when expenditure is being incurred, borrowing costs are being incurred, and activities to prepare asset are in progress.<br>\n<strong>Stop:</strong> when asset is ready for intended use or sale.",
    "plainAnswer": "A qualifying asset is one that necessarily takes a substantial period of time to get ready for its intended use or sale. Examples: manufacturing plants, power generation facilities, investment property under construction, intangible assets in development. Start capitalizing borrowing costs: when expenditure is being incurred, borrowing costs are being incurred, and activities to prepare asset are in progress. Stop: when asset is ready for intended use or sale.",
