    "topic": "Core Concepts & Standards",
    "question": "How do you treat prior period errors (IAS 8)?",
    "answerHtml": "<strong>Retrospective restatement:</strong><ul><li>Restate comparative amounts in prior period presented</li><li>If error occurred before earliest prior period presented: restate opening balances</li><li>Adjust retained earnings in SOCIE</li><li>Disclose nature, amount, and impact in notes</li></ul>",
    "plainAnswer": "Retrospective restatement: Restate comparative amounts in prior period presented If error occurred before earliest prior period presented: restate opening balances Adjust retained earnings in SOCIE Disclose nature, amount, and impact in notes",
