    "module": "far",
    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "What is the Right of Use (ROU) asset under IFRS 16?",
    "answerHtml": "<div class=\"def\">The lessee's right to use a leased asset over the lease term.</div>\n<strong>Initial measurement includes:</strong><ul><li>Present value of lease payments</li><li>Initial direct costs</li><li>Lease payments made at/before commencement</li><li>Estimated dismantling/restoration costs</li></ul>\nDepreciated over shorter of lease term or useful life.",
    "plainAnswer": "The lessee's right to use a leased asset over the lease term. Initial measurement includes: Present value of lease payments Initial direct costs Lease payments made at/before commencement Estimated dismantling/restoration costs Depreciated over shorter of lease term or useful life.",
