    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "What is the difference between IAS 16 (PPE) and IAS 40 (Investment Property)?",
    "answerHtml": "<table><tr><th>IAS 16 — PPE</th><th>IAS 40 — Investment Property</th></tr>\n<tr><td>Used in operations / admin</td><td>Held to earn rent or capital appreciation</td></tr>\n<tr><td>Cost or Revaluation model</td><td>Cost model or Fair Value model</td></tr>\n<tr><td>Depreciation always charged</td><td>No depreciation under Fair Value model</td></tr>\n<tr><td>Revaluation gains → OCI</td><td>Fair value gains → Profit or Loss</td></tr></table>",
    "plainAnswer": "IAS 16 — PPE IAS 40 — Investment Property Used in operations / admin Held to earn rent or capital appreciation Cost or Revaluation model Cost model or Fair Value model Depreciation always charged No depreciation under Fair Value model Revaluation gains → OCI Fair value gains → Profit or Loss",
