    "module": "far",
    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "Normal EPS vs. Diluted EPS?",
    "answerHtml": "<span class=\"formula\">Basic EPS = Profit attributable to ordinary shareholders / Weighted avg number of ordinary shares\nDiluted EPS = Adjusted profit / (Weighted avg shares + Potential dilutive shares from options, convertibles)</span>\nDiluted EPS is always ≤ Basic EPS.",
    "plainAnswer": "Basic EPS = Profit attributable to ordinary shareholders / Weighted avg number of ordinary shares Diluted EPS = Adjusted profit / (Weighted avg shares + Potential dilutive shares from options, convertibles) Diluted EPS is always ≤ Basic EPS.",
