    "question": "When can an internally generated intangible asset be capitalized (IAS 38)?",
    "answerHtml": "Only costs incurred in the <strong>development phase</strong> can be capitalized (if all 6 criteria met — PIRATE):<ul>\n<li><strong>P</strong>robable future economic benefits</li><li><strong>I</strong>ntention to complete</li><li><strong>R</strong>esources available</li><li><strong>A</strong>bility to use/sell</li><li><strong>T</strong>echnical feasibility</li><li><strong>E</strong>xpenditure measurable</li></ul>\nResearch phase costs: always expensed.",
    "plainAnswer": "Only costs incurred in the development phase can be capitalized (if all 6 criteria met — PIRATE): P robable future economic benefits I ntention to complete R esources available A bility to use/sell T echnical feasibility E xpenditure measurable Research phase costs: always expensed.",
