    "answerHtml": "<table><tr><th>Capital Expenditure</th><th>Revenue Expenditure</th></tr>\n<tr><td>Benefit over more than one period → capitalize as asset</td><td>Benefit in current period only → expense immediately</td></tr>\n<tr><td>Example: machinery, building extension</td><td>Example: repairs, maintenance, salaries</td></tr></table>",
