    "module": "far",
    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "What is goodwill and how is it tested for impairment (IFRS 3 / IAS 36)?",
    "answerHtml": "<span class=\"formula\">Goodwill = Consideration paid + NCI + FV of previously held interest – FV of net identifiable assets</span>\nUnder IFRS: NOT amortized. Tested for impairment annually at CGU level.<br>\nImpairment loss allocated: first to goodwill, then pro-rata to other assets.<br>\n<div class=\"warn\">Goodwill impairment CANNOT be reversed.</div>",
    "plainAnswer": "Goodwill = Consideration paid + NCI + FV of previously held interest – FV of net identifiable assets Under IFRS: NOT amortized. Tested for impairment annually at CGU level. Impairment loss allocated: first to goodwill, then pro-rata to other assets. Goodwill impairment CANNOT be reversed.",
