    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "Equity method vs. full consolidation?",
    "answerHtml": "<table><tr><th>Equity Method (IAS 28)</th><th>Full Consolidation (IFRS 10)</th></tr>\n<tr><td>Associates/JVs (20–50%)</td><td>Subsidiaries (>50% control)</td></tr>\n<tr><td>Single line: Investment in Associate in BS</td><td>Line-by-line combination of all assets/liabilities</td></tr>\n<tr><td>Share of profit in P&L</td><td>100% revenue/expenses + NCI</td></tr></table>",
    "plainAnswer": "Equity Method (IAS 28) Full Consolidation (IFRS 10) Associates/JVs (20–50%) Subsidiaries (>50% control) Single line: Investment in Associate in BS Line-by-line combination of all assets/liabilities Share of profit in P&L 100% revenue/expenses + NCI",
