    "topic": "Core Concepts & Standards",
    "question": "What is IFRS 5 — Non-current assets held for sale?",
    "answerHtml": "<strong>Classification criteria:</strong> Available for immediate sale + management committed + sale highly probable within 12 months.<br>\n<strong>Measurement:</strong> Lower of carrying amount or FV less costs to sell.<br>\nStop depreciating. Present separately on balance sheet under current assets.",
    "plainAnswer": "Classification criteria: Available for immediate sale + management committed + sale highly probable within 12 months. Measurement: Lower of carrying amount or FV less costs to sell. Stop depreciating. Present separately on balance sheet under current assets.",
