    "question": "Difference between defined benefit and defined contribution pension plans (IAS 19)?",
    "answerHtml": "<table><tr><th>Defined Contribution</th><th>Defined Benefit</th></tr>\n<tr><td>Fixed contributions — no further obligation</td><td>Employer guarantees final benefit amount</td></tr>\n<tr><td>Actuarial risk on employee</td><td>Actuarial risk on employer</td></tr>\n<tr><td>Simple: Dr Expense Cr Cash</td><td>Complex: actuarial valuation, PBO, plan assets, remeasurements to OCI</td></tr></table>",
