    "question": "How are share-based payments accounted for (IFRS 2)?",
    "answerHtml": "<strong>Equity-settled:</strong> Measure at FV at grant date; expense over vesting period.<br>\n<span class=\"formula\">Dr. Employee Expense (P&L)\n  Cr. Share-based Payment Reserve (Equity)</span>\n<strong>Cash-settled:</strong> Measure at FV of liability at each reporting date; remeasure through P&L.",
    "plainAnswer": "Equity-settled: Measure at FV at grant date; expense over vesting period. Dr. Employee Expense (P&L) Cr. Share-based Payment Reserve (Equity) Cash-settled: Measure at FV of liability at each reporting date; remeasure through P&L.",
