    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "How are government grants accounted for (IAS 20)?",
    "answerHtml": "<strong>For assets:</strong> Deduct from asset cost OR recognize as deferred income and release over useful life.<br>\n<strong>For income:</strong> Recognize in P&L when related expenditure is incurred.<br>\n<div class=\"tip\">Only recognize grant when reasonable assurance exists that conditions will be met and grant will be received.</div>",
    "plainAnswer": "For assets: Deduct from asset cost OR recognize as deferred income and release over useful life. For income: Recognize in P&L when related expenditure is incurred. Only recognize grant when reasonable assurance exists that conditions will be met and grant will be received.",
