    "module": "far",
    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "What is the going concern basis of accounting?",
    "answerHtml": "<div class=\"def\">Assumption that the entity will continue operations for the foreseeable future (minimum 12 months from reporting date).</div>\nIf NOT appropriate: prepare FS on break-up basis (assets at liquidation values, all liabilities current, additional provisions). Management's responsibility (IAS 1). Auditor evaluates (ISA 570).",
    "plainAnswer": "Assumption that the entity will continue operations for the foreseeable future (minimum 12 months from reporting date). If NOT appropriate: prepare FS on break-up basis (assets at liquidation values, all liabilities current, additional provisions). Management's responsibility (IAS 1). Auditor evaluates (ISA 570).",
