    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "Difference between IAS 16 revaluation model and cost model?",
    "answerHtml": "<table><tr><th>Cost Model</th><th>Revaluation Model</th></tr>\n<tr><td>Cost – Accumulated depreciation – Impairment</td><td>Fair value at revaluation date – subsequent depreciation – impairment</td></tr>\n<tr><td>No revaluation surplus</td><td>Surplus in OCI / revaluation reserve</td></tr>\n<tr><td>Simpler; more common</td><td>Requires regular FV assessments; depreciates on revalued amount</td></tr></table>",
    "plainAnswer": "Cost Model Revaluation Model Cost – Accumulated depreciation – Impairment Fair value at revaluation date – subsequent depreciation – impairment No revaluation surplus Surplus in OCI / revaluation reserve Simpler; more common Requires regular FV assessments; depreciates on revalued amount",
