    "module": "far",
    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "How is a sale-and-leaseback transaction accounted for under IFRS 16?",
    "answerHtml": "<strong>If the transfer is a sale (IFRS 15 conditions met):</strong><ul>\n<li>Seller-lessee: Derecognize asset, recognize ROU asset for retained interest, recognize gain/loss only for rights transferred to buyer-lessor</li></ul>\n<strong>If NOT a sale:</strong> Treat as a secured borrowing — asset stays on books, proceeds as financial liability. No sale recognized.",
    "plainAnswer": "If the transfer is a sale (IFRS 15 conditions met): Seller-lessee: Derecognize asset, recognize ROU asset for retained interest, recognize gain/loss only for rights transferred to buyer-lessor If NOT a sale: Treat as a secured borrowing — asset stays on books, proceeds as financial liability. No sale recognized.",
    "idealAnswerPoints": [
      "Seller-lessee: Derecognize asset, recognize ROU asset for retained interest, recognize gain/loss only for rights transferred to buyer-lessor",
      "If the transfer is a sale (IFRS 15 conditions met)",
      "If NOT a sale"
    ],
    "difficulty": "Advanced",
