    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "What is the difference between current and deferred tax?",
    "answerHtml": "<table><tr><th>Current Tax</th><th>Deferred Tax</th></tr>\n<tr><td>Tax payable/recoverable for current period</td><td>Tax arising from temporary differences</td></tr>\n<tr><td>Based on taxable income × current tax rate</td><td>Temporary difference × enacted future tax rate</td></tr>\n<tr><td>Liability (or asset) on balance sheet</td><td>DTL or DTA on balance sheet</td></tr></table>",
    "plainAnswer": "Current Tax Deferred Tax Tax payable/recoverable for current period Tax arising from temporary differences Based on taxable income × current tax rate Temporary difference × enacted future tax rate Liability (or asset) on balance sheet DTL or DTA on balance sheet",
