    "category": "Financial Accounting & Reporting (IFRS)",
    "topic": "Core Concepts & Standards",
    "question": "What is the difference between gross profit margin and net profit margin?",
    "answerHtml": "<span class=\"formula\">Gross Profit Margin = (Revenue – COGS) / Revenue × 100\nNet Profit Margin = Net Profit After Tax / Revenue × 100</span>\nGPM measures production/trading efficiency. NPM measures overall profitability after all costs including admin, finance, and tax. A high GPM but low NPM suggests high operating/finance costs.",
    "plainAnswer": "Gross Profit Margin = (Revenue – COGS) / Revenue × 100 Net Profit Margin = Net Profit After Tax / Revenue × 100 GPM measures production/trading efficiency. NPM measures overall profitability after all costs including admin, finance, and tax. A high GPM but low NPM suggests high operating/finance costs.",
    "idealAnswerPoints": [
      "Standard professional application",
      "Clear reasoning with standard references"
    ],
