export const getQuestionsForInterview = ({
  targetRole = 'Audit Trainee (Articleship)',
  interviewStage = 'Technical Round',
  difficulty = 'Intermediate',
  interviewType = 'Technical',
  count = 5,
  isBig4 = false
}) => {
  let filtered = [...QUESTION_BANK];

  const typeLower = (interviewType || '').toLowerCase();
  const stageLower = (interviewStage || '').toLowerCase();
  const roleLower = (targetRole || '').toLowerCase();

  if (typeLower.includes('behavioral') || stageLower.includes('hr') || stageLower.includes('screening')) {
    filtered = filtered.filter(q => q.module === 'behavioral' || q.module === 'aptitude');
  } else if (typeLower.includes('technical')) {
    if (roleLower.includes('tax')) {
      filtered = filtered.filter(q => q.module === 'taxation' || q.module === 'far' || q.module === 'companylaw');
    } else if (roleLower.includes('audit')) {
      filtered = filtered.filter(q => q.module === 'audit' || q.module === 'far' || q.module === 'companylaw' || q.module === 'behavioral');
    } else {
      filtered = filtered.filter(q => q.module === 'far' || q.module === 'audit' || q.module === 'taxation' || q.module === 'companylaw');
    }
  } else if (typeLower.includes('scenario')) {
    filtered = filtered.filter(q => q.topic.toLowerCase().includes('dilemmas') || q.topic.toLowerCase().includes('client') || q.module === 'audit');
  }

  // Shuffle filtered pool
  const shuffled = filtered.sort(() => 0.5 - Math.random());
  return shuffled.slice(0, count);
};

export const getQuestionsByTopic = (topicName) => {
  return QUESTION_BANK.filter(q => q.topic.toLowerCase().includes(topicName.toLowerCase()) || q.module.toLowerCase() === topicName.toLowerCase());
};
